// adler32: the Adler-32 checksum of 8 MiB of generated bytes.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    const int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761LL >> 13) & 255);
    uint32_t a = 1, b = 0;
    for (int64_t i = 0; i < n; i++) {
        a = (a + data[i]) % 65521;
        b = (b + a) % 65521;
    }
    printf("%u\n", b << 16 | a);
    free(data);
    return 0;
}
